function exactPrefix(prefix: seq<PublishedRecord>, full: seq<PublishedRecord>): bool
{
  var local_0 := Std.Collections.Seq.FoldLeft((acc: PrefixCheck, row: PublishedRecord) => PrefixCheck((acc.offset + 1), (acc.exact && (row == (if ((0 <= acc.offset) && (acc.offset < |full|)) then full[acc.offset] else absentRecord)))), PrefixCheck(0, true), prefix);
  ((|prefix| <= |full|) && local_0.exact)
}

function admissiblePublication(p: Publication, candidate: seq<PublishedRecord>): bool
{
  ((exactPrefix(p.visible, candidate) && exactPrefix(candidate, p.canonical)) && uniqueRecords(candidate))
}

function canObserveCanonical(p: Publication, snapshot: seq<PublishedRecord>, verified: bool): bool
{
  ((verified && exactPrefix(p.canonical, snapshot)) && uniqueRecords(snapshot))
}

function canPublish(p: Publication): bool
{
  ((p.phase.Staged? && (p.preparedAt == p.revision)) && admissiblePublication(p, p.staged))
}

function canPublishConcurrent(p: Publication, candidate: seq<PublishedRecord>): bool
{
  (admissiblePublication(p, candidate) && (|candidate| > |p.visible|))
}

