function enabled(current: Publication, event: Event): bool
{
  match event {
    case stage(i_event_candidate) =>
      canStage(current)
    case observeCanonical(i_event_snapshot, i_event_verified) =>
      canObserveCanonical(current, i_event_snapshot, i_event_verified)
    case publish =>
      canPublish(current)
    case publishConcurrent(i_event_candidate) =>
      canPublishConcurrent(current, i_event_candidate)
    case reject =>
      canReject(current)
    case interrupt =>
      canInterrupt(current)
  }
}

function step(current: Publication, event: Event): Publication
  requires inv(current)
{
  if (event.stage? && canStage(current)) then
    stage(current, event.candidate)
  else
    if (event.observeCanonical? && canObserveCanonical(current, event.snapshot, event.verified)) then
      observeCanonical(current, event.snapshot, event.verified)
    else
      if (event.publish? && canPublish(current)) then
        publish(current)
      else
        if (event.publishConcurrent? && canPublishConcurrent(current, event.candidate)) then
          publishConcurrent(current, event.candidate)
        else
          if (event.reject? && canReject(current)) then
            reject(current)
          else
            if (event.interrupt? && canInterrupt(current)) then
              interrupt(current)
            else
              current
}

lemma step_ensures(current: Publication, event: Event)
  requires inv(current)
  ensures inv(step(current, event))
{
  hide *;
  reveal step, inv;
  match event {
    case stage(i_candidate) => stage_ensures(current, i_candidate);
    case observeCanonical(i_snapshot, i_verified) => observeCanonical_ensures(current, i_snapshot, i_verified);
    case publish => publish_ensures(current);
    case publishConcurrent(i_candidate) => publishConcurrent_ensures(current, i_candidate);
    case reject => reject_ensures(current);
    case interrupt => interrupt_ensures(current);
  }
}

